class Solution {
public:
    bool checkDistances(std::string s, std::vector<int>& distance) {
        std::vector<int> first(26, -1);
        for (int i = 0; i < (int)s.size(); i++) {
            int idx = s[i] - 'a';
            if (first[idx] != -1) {
                if (i - first[idx] - 1 != distance[idx]) return false;
            } else {
                first[idx] = i;
            }
        }
        return true;
    }
};

class Solution {
    public boolean checkDistances(String s, int[] distance) {
        int[] first = new int[26];
        java.util.Arrays.fill(first, -1);
        for (int i = 0; i < s.length(); i++) {
            int idx = s.charAt(i) - 'a';
            if (first[idx] != -1) {
                if (i - first[idx] - 1 != distance[idx]) return false;
            } else {
                first[idx] = i;
            }
        }
        return true;
    }
}

var checkDistances = function(s, distance) {
    const first = new Map();
    for (let i = 0; i < s.length; i++) {
        const ch = s[i];
        if (first.has(ch)) {
            const expected = distance[ch.charCodeAt(0) - 97];
            if (i - first.get(ch) - 1 !== expected) return false;
        } else {
            first.set(ch, i);
        }
    }
    return true;
};
